# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: Live check of the start.gg API layer (ds.data.raw.startgg) for a few players:
# does the supermajor id map to a start.gg player, what one set costs against the 1000-object
# limit, how many games carry characters / a stage, and how long a capped fetch takes.
# Its numbers go into the Site notes in pkgs/ds/data/raw/startgg/client.py.
# Needs a start.gg API token: `ds settings sync` (or export STARTGG_API_TOKEN).
#
# Example CLI Commands:
#   0. Sparg0 and rm8:       uv run scripts/startgg_probe.py
#   1. Tag, id or profile:   uv run scripts/startgg_probe.py DeLulu 158026 user/abc123
#   2. Smaller window:       uv run scripts/startgg_probe.py Sparg0 --months 3 --max-sets 60
#   3. Also other queries:   uv run scripts/startgg_probe.py Sparg0 --extra
# ---------------------------------------------------------------------------
from __future__ import annotations

import asyncio
import datetime as dt
import time
from typing import Annotated

import typer
from ds.data.raw import startgg
from ds.data.raw.startgg import client
from ds.data.raw.supermajor import pick_player, search_players
from rich import print as rprint

app = typer.Typer()
_COST_PER_PAGE = 60  # sets asked for in the cost check; meant to be over the limit


async def _resolve(player: str) -> startgg.Player:
    """Tag (via supermajor search), start.gg player id, or start.gg profile url / slug"""
    if player.isdigit():
        return await startgg.player(int(player))
    if "user/" in player:
        return await startgg.user_player(player)
    lookup = pick_player(player, search_players(player))
    match = lookup.player
    found = await startgg.player(int(match.player_id.removeprefix("S")))
    same = "[green]same tag[/green]" if found.tag.casefold() == match.tag.casefold() else "[red]DIFFERENT TAG[/red]"
    rprint(f"  supermajor {match.player_id} ({match.tag}, {match.num_events} events) -> start.gg {found.id}: {same}")
    return found


async def _set_cost(player_id: int) -> None:
    """Ask for more sets than fit; start.gg's refusal says how many objects that would be"""
    try:
        page = await startgg.player_sets_page(player_id, per_page=_COST_PER_PAGE)
    except client.ComplexityError as e:
        per_set = (e.actual or 0) / _COST_PER_PAGE
        fits = int(client.MAX_OBJECTS_PER_REQUEST / per_set) if per_set else 0
        rprint(f"  cost: {e.actual} objects for {_COST_PER_PAGE} sets = {per_set:.1f} per set -> {fits} sets fit")
    else:
        rprint(f"  cost: {_COST_PER_PAGE} sets fit in one request ({len(page.sets)} returned)")


def _pct(part: int, whole: int) -> str:
    return f"{part}/{whole} ({part / whole:.0%})" if whole else "0/0"


async def _probe(player: str, months: int, max_sets: int) -> startgg.Player:
    rprint(f"\n[bold]{player}[/bold]")
    who = await _resolve(player)
    rprint(f"  player: {who.tag} (id {who.id}, prefix {who.prefix}, profile {who.user_slug})")
    await _set_cost(who.id)

    since = dt.datetime.now(dt.UTC) - dt.timedelta(days=30 * months)
    requests_before = len(client._request_times)  # noqa: SLF001  # the probe reports the client's own counter
    start = time.perf_counter()
    sets = await startgg.player_sets(who.id, max_sets=max_sets, since=since)
    seconds = time.perf_counter() - start
    requests = len(client._request_times) - requests_before  # noqa: SLF001
    rprint(f"  fetch: {len(sets)} sets (cap {max_sets}, {months} months) in {seconds:.1f}s, {requests} requests")
    if not sets:
        return who
    rprint(f"  span: {sets[-1].completed_at:%Y-%m-%d} to {sets[0].completed_at:%Y-%m-%d}")

    games = [(s, g) for s in sets for g in s.games]
    mine = [g.character_of(s.side_of(who.id).entrant_id) for s, g in games if s.side_of(who.id)]
    theirs = [g.character_of(s.opponent_of(who.id).entrant_id) for s, g in games if s.opponent_of(who.id)]
    both = sum(1 for a, b in zip(mine, theirs, strict=False) if a and b)
    rprint(f"  sets with games reported: {_pct(sum(1 for s in sets if s.games), len(sets))}")
    rprint(f"  games: {len(games)}; with own character: {_pct(sum(1 for c in mine if c), len(games))}")
    rprint(f"  games with both characters: {_pct(both, len(games))}")
    rprint(f"  games with a stage: {_pct(sum(1 for _, g in games if g.stage), len(games))}")
    rprint(f"  games with a winner: {_pct(sum(1 for _, g in games if g.winner_entrant_id), len(games))}")
    rprint(f"  sets with a VOD: {_pct(sum(1 for s in sets if s.vod_url), len(sets))}")
    rprint(f"  events: {len({s.event.id for s in sets if s.event})}")
    unmapped = sorted({c.name for c in [*mine, *theirs] if c and c.char_group is None})
    rprint(f"  characters without a char_group: {unmapped or 'none'}")
    newest = sets[0]
    rprint(f"  newest set: {newest.display_score!r}, {newest.round_text}, {newest.event.slug if newest.event else '?'}")
    return who


async def _extra(who: startgg.Player) -> None:
    """One small call to each of the other queries, to confirm they run"""
    rprint("\n[bold]Other queries[/bold]")
    stages = await startgg.videogame_stages()
    rprint(f"  videogame: {len(await startgg.videogame_characters())} characters, {len(stages)} stages")
    found = await startgg.tournaments(country="US", upcoming=True, per_page=5)
    rprint(f"  tournaments (US, upcoming): {found.page_info.total} total; first: {[t.name for t in found.tournaments]}")
    sets = await startgg.player_sets(who.id, max_sets=1)
    if sets and sets[0].event:
        event = sets[0].event.slug
        entrants = await startgg.event_entrants(event, per_page=5)
        rprint(f"  entrants of {event}: {entrants.page_info.total} total; {[e.name for e in entrants.entrants]}")
        standings = await startgg.event_standings(event, per_page=3)
        rprint(f"  standings: {[(e.placement, e.name) for e in standings.entrants]}")
        rival = sets[0].opponent_of(who.id)
        if rival and rival.players:
            h2h = await startgg.player_sets(who.id, opponent_id=rival.players[0].id, max_sets=20)
            rprint(f"  head-to-head vs {rival.players[0].tag}: {len(h2h)} sets")
    mine = await startgg.my_tournaments()
    rprint(f"  my upcoming tournaments: {[t.name for t in mine.tournaments]}")


async def _run(players: list[str], months: int, max_sets: int, extra: bool) -> None:
    who = None
    for player in players:
        who = await _probe(player, months, max_sets)
    if extra and who:
        await _extra(who)


@app.command()
def main(
    players: Annotated[
        list[str] | None, typer.Argument(help="Tags, start.gg player ids or profile urls (default: Sparg0 rm8)")
    ] = None,
    months: Annotated[int, typer.Option(help="How far back to fetch sets")] = 6,
    max_sets: Annotated[int, typer.Option(help="Stop after this many sets")] = 150,
    extra: Annotated[bool, typer.Option("--extra", help="Also run the tournament / entrant queries once")] = False,
) -> None:
    """Print coverage, cost and timing of start.gg data for each player."""
    try:
        asyncio.run(_run(players or ["Sparg0", "rm8"], months, max_sets, extra))
    except (startgg.StartggError, ValueError) as e:
        rprint(f"[red]{e}[/red]")
        raise typer.Exit(1) from e


if __name__ == "__main__":
    app()
